const fmt = String($('Config').first().json.format || 'carousel').toLowerCase();
const cr = $('Creative Agent').first().json.output;
const style = cr.visual_style || '';
const ratio = fmt === 'reel' ? '9:16' : '4:5';
const height = fmt === 'reel' ? 1920 : 1350;
const mk = (name, prompt, headline) => ({
  name, aspect: ratio, width: 1080, height,
  image_prompt: `${prompt}. ` + (headline ? `Include this exact headline text, bold and clearly legible, spelled exactly: "${headline}". ` : '') +
    `Visual style: ${style}. Polished Instagram ${fmt === 'reel' ? 'reel cover' : 'post'} graphic, aspect ratio ${ratio}, no watermark, no logos.`
});
const items = [mk('cover', cr.cover.image_prompt, cr.cover.headline)];
if (fmt === 'carousel') (cr.slides || []).slice(0, 6).forEach((s, i) => items.push(mk('slide_' + (i + 1), s.image_prompt, s.headline)));
return items.map(j => ({ json: j }));

const posts = $('Build Image Prompts').all();
const out = [];
const items = $input.all();
for (let i = 0; i < items.length; i++) {
  const res = items[i].json;
  const parts = (res.candidates && res.candidates[0] && res.candidates[0].content && res.candidates[0].content.parts) || [];
  const img = parts.find((p) => p.inlineData || p.inline_data);
  if (!img) throw new Error('No image returned for ' + posts[i].json.name + ': ' + JSON.stringify(res).slice(0, 400));
  const data = img.inlineData || img.inline_data;
  out.push({
    json: posts[i].json,
    binary: { data: await this.helpers.prepareBinaryData(Buffer.from(data.data, 'base64'), posts[i].json.name + '.png', data.mimeType || data.mime_type || 'image/png') },
    pairedItem: { item: i },
  });
}
return out;

const urls = $input.all().map(i => (i.json.data && (i.json.data.url || i.json.data.display_url)) || '').filter(Boolean);
if (!urls.length) throw new Error('imgbb returned no URLs - check imgbb_api_key in Config');
return [{ json: { urls, cover_url: urls[0], count: urls.length } }];

const ids = $input.all().map(i => String((i.json.data && i.json.data.id) || '')).filter(Boolean);
if (ids.length < 2) throw new Error('Carousel needs at least 2 child containers, got ' + ids.length + ': ' + JSON.stringify($input.all().map(i => i.json)).slice(0, 400));
return [{ json: { children: ids } }];

const o = ($input.first().json || {}).output;
if (!o || !Array.isArray(o.script_scenes) || !o.script_scenes.length) {
  const v = $('Validator Agent').first().json.output || {};
  throw new Error('Strategist returned no script. Strategist output: ' + JSON.stringify($input.first().json).slice(0, 600) +
    ' | Validator approved ideas: ' + ((v.approved_ideas || []).length) + ' | Validator summary: ' + (v.validation_summary || 'none'));
}
return $input.all();

const f = $input.first().json;
const v = (k) => String(f[k] || '').trim();
return [{ json: { body: {
  format: v('Format'), topic: v('Topic'), niche: v('Niche'), audience: v('Audience'),
  language: v('Language'), brand_voice: v('Brand Voice'), geo: v('Country'),
  instructions: v('Instructions'), image_model: v('Image Model')
} } }];
